import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Actions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/actions.md","filePath":"reference/actions.md"}'),i={name:"reference/actions.md"};function d(n,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h1><p>The installed configuration exposes lifecycle actions through a local kitty kitten. They apply to OS windows in the current kitty process. Separate kitty processes keep separate state.</p><h2 id="default-keyboard-controls" tabindex="-1">Default keyboard controls <a class="header-anchor" href="#default-keyboard-controls" aria-label="Permalink to &quot;Default keyboard controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td>Ctrl+Shift+F6</td><td><code>status</code></td></tr><tr><td>Ctrl+Shift+F7</td><td><code>pause</code></td></tr><tr><td>Ctrl+Shift+F8</td><td><code>resume</code></td></tr><tr><td>Ctrl+Shift+F9</td><td><code>reload</code></td></tr><tr><td>Ctrl+Shift+F10</td><td><code>restore</code></td></tr></tbody></table><p>Review these bindings during <a href="./../guide/installation.html">installation preview</a>, especially if your configuration already uses those keys. Status opens in a scrollback overlay so it does not print over the shell prompt.</p><h2 id="lifecycle-contract" tabindex="-1">Lifecycle contract <a class="header-anchor" href="#lifecycle-contract" aria-label="Permalink to &quot;Lifecycle contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th><th>Failure and recovery</th></tr></thead><tbody><tr><td><code>status</code></td><td>Report diagnostic reason, pending work, active panes, ownership, paused state, and upload counts.</td><td>A missing report or unsupported profile is a diagnostic, not a support claim.</td></tr><tr><td><code>reload</code></td><td>Asynchronously validate <code>kittyscape.json</code>, refresh the image cache, and re-evaluate active contexts.</td><td>Malformed rules retain the last valid configuration. Fix the file and reload again.</td></tr><tr><td><code>pause</code></td><td>Restore owned baselines, then pause the instance, including windows opened later.</td><td>Windows changed by another writer keep that writer’s image.</td></tr><tr><td><code>resume</code></td><td>Resume using a known baseline captured at startup or an observed external write.</td><td>A window with an unknown baseline stays paused. Resume never guesses GPU state.</td></tr><tr><td><code>restore</code></td><td>Restore owned baselines and pause the instance, exactly like <code>pause</code>. Useful before removal.</td><td>Never overwrite a background installed by another writer.</td></tr></tbody></table><p>Setting <code>enabled</code> to <code>false</code>, then reloading, restores owned images and disables automatic switching. Reload and disable do not rewrite <code>kitty.conf</code>.</p><p>A failed restore remains labeled <code>restore-failed</code> while ownership is retained. Resolve the failure and retry <code>restore</code> before removing files. Resume, reload, or a changed directory can retry a transient upload failure; unchanged prompts retain the error without repeatedly uploading the same failed image.</p><p>Status includes a bounded, privacy-safe <code>detail</code> for configuration errors, such as a JSON line/column or <code>rules[0].image</code>. A <code>filesystem-timeout</code> stops collection after five seconds, with the running read retained as <code>filesystem_stalled</code>. No additional work is submitted behind it. Once the read finishes, a new event or reload can recover.</p><h2 id="ownership-changes" tabindex="-1">Ownership changes <a class="header-anchor" href="#ownership-changes" aria-label="Permalink to &quot;Ownership changes&quot;">​</a></h2><p>An observed external background write pauses the affected OS window. Other OS windows keep their own state. An explicit resume can continue when a current baseline is known. Unknown or ambiguous baselines stay paused until a qualified startup/configuration establishes one.</p><p>The <a href="./../development/compatibility-findings.html">runtime findings</a> record the action behavior established in graphical tests.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>Normal diagnostics are bounded and omit local directory names, usernames, image paths, and command lines. The graphical test harness deliberately records fixture paths; review any additional logs before sharing. Diagnostic actions use the local kitty process and need no remote-control listener.</p>',15)])])}const f=t(i,[["render",d]]);export{p as __pageData,f as default};
